window.AUTH=window.AUTH||{};window.AUTH["18-302"]={"d":"18-302","id":"2018/18-302","n":"Iancu v. Brunetti","briefs":[{"k":"petitioner","label":"Brief of petitioner Andrei Iancu, Under Secretary of Commerce for Intellectual Property and Director, United States Patent and Trademark Office","date":"2019-02-15","url":"https://www.supremecourt.gov/DocketPDF/18/18-302/88668/20190215143121362_18-302tsUnitedStates.pdf","side":"pet","n":83},{"k":"respondent","label":"Brief of respondent Erik Brunetti","date":"2019-03-18","url":"https://www.supremecourt.gov/DocketPDF/18/18-302/92328/20190318175238286_37643%20pdf%20Sommer%20br.pdf","side":"res","n":58},{"k":"reply","label":"Reply of petitioner Andrei Iancu, Under Secretary of Commerce for Intellectual Property and Director, United States Patent and Trademark Office","date":"2019-04-02","url":"https://www.supremecourt.gov/DocketPDF/18/18-302/95141/20190402150636686_18-302rbUnitedStates.pdf","side":"pet","n":43}],"opinion":"https://www.supremecourt.gov/opinions/18pdf/18-302_e29g.pdf","tr":true,"items":[{"t":"case","label":"Abood v. Detroit Bd. of Educ.","cite":"431 U.S. 209","y":1977,"id":"1976/75-1153","sc":1,"by":{"0":"42"}},{"t":"case","label":"Agency for Int’l Dev. v. Alliance for Open Soc’y Int’l, Inc.","cite":"570 U.S. 205","y":2013,"id":"2012/12-10","sc":1,"by":{"0":"12, 23, 31, 32, 38, 40","2":"12"},"q":[{"src":"brief","b":0,"text":"to regulate speech outside the contours of the [trademarkregistration] program itself.","cite":"570 U.S. at 214"},{"src":"brief","b":0,"text":"conditions that define the federal program and those that reach outside it.","cite":"570 U.S. at 217"},{"src":"brief","b":2,"text":"to regulate speech outside the contours of the [government] program itself,","cite":"570 U.S. 205, 214-216"}]},{"t":"case","label":"American Freedom Def. Initiative v. Washington Metro. Area Transit Auth.","cite":"901 F.3d 356","y":2018,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/901/356/","by":{"0":"30"}},{"t":"case","label":"B & B Hardware, Inc. v. Hargis Indus., Inc.","cite":"135 S. Ct. 1293","y":2015,"id":"2014/13-352","sc":1,"by":{"0":"2, 3, 4, 20"},"q":[{"src":"brief","b":0,"text":"The principle underlying trademark protection is that distinctive marks—words, names, symbols, and the like—can help distinguish a particular artisan’s goods from those of others.","cite":"135 S. Ct. 1293, 1299"},{"src":"brief","b":0,"text":"[o]ne who first uses a distinct mark in commerce * * * acquires rights to that mark.","cite":"135 S. Ct. at 1299"}]},{"t":"case","label":"Bethel Sch. Dist. No. 403 v. Fraser","cite":"478 U.S. 675","y":1986,"id":"1985/84-1667","sc":1,"by":{"0":"29","2":"8"},"q":[{"src":"brief","b":0,"text":"not to [a] point of view, but to the way in which it [wa]s expressed.","cite":"478 U.S. 675"},{"src":"argument","who":"Mr. Sommer","text":"Well, I'm not sure -- at least in the high school context, like Bethel School, I think that there is disruption."}]},{"t":"case","label":"Broadrick v. Oklahoma","cite":"413 U.S. 601","y":1973,"id":"1972/71-1639","sc":1,"by":{"0":"47"}},{"t":"case","label":"Central Hudson Gas & Elec. Corp. v. Public Serv. Comm’n","cite":"447 U.S. 557","y":1980,"id":"1979/79-565","sc":1,"by":{"0":"10, 37","1":"9, 20, 21, 32","2":"16"},"q":[{"src":"brief","b":0,"text":"the commonsense distinction between speech proposing a commercial transaction, which occurs in an area traditionally subject to government regulation, and other varieties of speech.","cite":"447 U.S. 557, 562"}]},{"t":"case","label":"Christian Legal Soc’y Chapter of the Univ. of Cal., Hastings Coll. of the Law v. Martinez","cite":"561 U.S. 661","y":2010,"id":"2009/08-1371","sc":1,"by":{"0":"22, 24","2":"4, 5, 6, 14"}},{"t":"case","label":"Cohen v. California","cite":"403 U.S. 15","y":1971,"id":"1970/299","sc":1,"by":{"0":"29","1":"passim","2":"9"},"q":[{"src":"brief","b":1,"text":"Thus, we deal here with a conviction resting solely upon ‘speech’. . . .","cite":"403 U.S. at 18"}]},{"t":"case","label":"Cornelius v. NAACP Legal Def. & Educ. Fund, Inc.","cite":"473 U.S. 788","y":1985,"id":"1984/84-312","sc":1,"by":{"0":"23, 35"},"q":[{"src":"brief","b":0,"text":"limitations on speech may be justified by [an] interest in ‘avoiding the appearance of political favoritism.’","cite":"473 U.S. at 809"},{"src":"argument","who":"Justice Sotomayor","text":"But I'm not sure how to differentiate this from a limited public forum, as we recognized in Cornelius, because, as in Cornelius, registrants can go out and use the trademark, they could have sought donations from whomever they wanted in Cornelius, and yet we talked and we held that the list of -- of -- of organizations was the forum."}]},{"t":"case","label":"Dastar Corp. v. Twentieth Century Fox Film Corp.","cite":"539 U.S. 23","y":2003,"id":"2002/02-428","sc":1,"by":{"0":"44","2":"16"},"q":[{"src":"brief","b":0,"text":"[f ]ederal trademark law ‘has no necessary relation to invention or discovery,’","cite":"539 U.S. 23, 34"},{"src":"brief","b":2,"text":"has no necessary relation to invention or discovery,","cite":"539 U.S. 23, 34"}]},{"t":"case","label":"Davenport v. Washington Educ. Ass’n","cite":"551 U.S. 177","y":2007,"id":"2006/05-1589","sc":1,"by":{"0":"19, 22, 23, 41, 42","1":"30","2":"4, 5, 13"},"q":[{"src":"brief","b":0,"text":"the government is acting in a capacity other than as regulator.","cite":"551 U.S. 177, 188"},{"src":"brief","b":0,"text":"[t]he risk that content-based distinctions will impermissibly interfere with the marketplace of ideas is sometimes attenuated when the government is acting in a capacity other than as regulator.","cite":"551 U.S. at 188"},{"src":"brief","b":1,"text":"act[s] in a capacity other than as regulator.","cite":"551 U.S. at 188, 190"},{"src":"brief","b":2,"text":"the government is acting in a capacity other than as regulator,","cite":"551 U.S. 177, 188"}]},{"t":"case","label":"De Walt, Inc. v. Magna Power Tool Corp.","cite":"289 F.2d 656","y":1961,"court":"C.C.P.A.","url":"https://www.courtlistener.com/c/F.2d/289/656/","by":{"0":"46"}},{"t":"case","label":"Eldred v. Ashcroft","cite":"537 U.S. 186","y":2003,"id":"2002/01-618","sc":1,"by":{"0":"44","2":"17"},"q":[{"src":"brief","b":0,"text":"suppl[ying] the economic incentive to create and disseminate ideas.","cite":"537 U.S. 186, 219"},{"src":"brief","b":2,"text":"supplies the economic incentive to create and disseminate ideas,","cite":"537 U.S. 186, 219"}]},{"t":"case","label":"FCC v. Pacifica Found.","cite":"438 U.S. 726","y":1978,"id":"1977/77-528","sc":1,"by":{"0":"28, 33","1":"9, 14, 17","2":"8, 9, 20"},"q":[{"src":"brief","b":0,"text":"offend for the same reasons that obscenity offends,","cite":"438 U.S. 726, 746"},{"src":"brief","b":2,"text":"not to this point of view, but to the way in which it is expressed.","cite":"438 U.S. at 746 n.22"},{"src":"argument","who":"Mr. Stewart","text":"If you look, for instance, at George Carlin's filthy words monologue, the monologue that was at issue in Pacifica, that's a paradigmatic example of profane copyrightable expression."}]},{"t":"case","label":"Friedman v. Rogers","cite":"440 U.S. 1","y":1979,"id":"1978/77-1163","sc":1,"by":{"0":"36"}},{"t":"case","label":"General Media Commc’ns, Inc. v. Cohen","cite":"131 F.3d 273","y":1997,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/131/273/","by":{"0":"30"}},{"t":"case","label":"Griffin v. Department of Veterans Affairs","cite":"274 F.3d 818","y":2001,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/274/818/","by":{"0":"30"}},{"t":"case","label":"Janus v. AFSCME","cite":"138 S. Ct. 2448","y":2018,"id":"2017/16-1466","sc":1,"by":{"0":"42"}},{"t":"case","label":"Maher v. Roe","cite":"432 U.S. 464","y":1977,"id":"1976/75-1440","sc":1,"by":{"0":"22","2":"4"},"q":[{"src":"brief","b":2,"text":"basic difference between direct state interference with a protected activity and state encouragement of an alternative activity consonant with legislative policy.","cite":"432 U.S. 464, 475"}]},{"t":"case","label":"Matal v. Tam","cite":"137 S. Ct. 1744","y":2017,"id":"2016/15-1293","sc":1,"by":{"0":"passim","1":"passim","2":"7, 8, 18"},"q":[{"src":"brief","b":0,"text":"Trademarks and their precursors have ancient origins, and trademarks were protected at common law and in equity at the time of the founding of our country.","cite":"137 S. Ct. 1744, 1751"},{"src":"brief","b":0,"text":"under state common law, or if [the mark] has been registered in a State, under that State’s registration system.","cite":"137 S. Ct. at 1753"},{"src":"brief","b":1,"text":"the public expression of ideas may not be prohibited merely because the ideas are themselves offensive to some of their hearers.","cite":"137 S. Ct. at 1763"},{"src":"brief","b":1,"text":"[t]he regulatory technique may extend only as far as the interest it serves.","cite":"137 S. Ct. at 1764"}]},{"t":"case","label":"Miller v. California","cite":"413 U.S. 15","y":1973,"id":"1971/70-73","sc":1,"by":{"0":"28, 45","1":"37, 59, 60"}},{"t":"case","label":"Mishawaka Rubber & Woolen Mfg. Co. v. S. S. Kresge Co.","cite":"316 U.S. 203","y":1942,"id":"scdb/1941-095","sc":1,"by":{"0":"3, 36"},"q":[{"src":"brief","b":0,"text":"to convey through the mark, in the minds of potential customers, the desirability of the commodity upon which it appears,","cite":"316 U.S. at 205"}]},{"t":"case","label":"Mitchell Bros. Film Grp. v. Cinema Adult Theater","cite":"604 F.2d 852","y":1979,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/604/852/","by":{"0":"45"}},{"t":"case","label":"National Endowment for the Arts v. Finley","cite":"524 U.S. 569","y":1998,"id":"1997/97-371","sc":1,"by":{"0":"18","1":"29","2":"4, 6, 20, 21"},"q":[{"src":"brief","b":1,"text":"leverage its power to award subsidies on the basis of subjective criteria into a penalty on disfavored viewpoints.","cite":"524 U.S. 569, 585, 587"},{"src":"brief","b":2,"text":"the consequences of imprecision are not constitutionally severe.","cite":"524 U.S. at 588"}]},{"t":"case","label":"PMG Int’l Div., L.L.C. v. Rumsfeld","cite":"303 F.3d 1163","y":2002,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/303/1163/","by":{"0":"30"}},{"t":"case","label":"Park ’N Fly, Inc. v. Dollar Park & Fly, Inc.","cite":"469 U.S. 189","y":1985,"id":"1984/83-1132","sc":1,"by":{"0":"5, 20, 22"}},{"t":"case","label":"Perry v. McDonald","cite":"280 F.3d 159","y":2001,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/280/159/","by":{"0":"29"}},{"t":"case","label":"Perry Educ. Ass’n v. Perry Local Educators’ Ass’n","cite":"460 U.S. 37","y":1983,"id":"1982/81-896","sc":1,"by":{"0":"12, 25","1":"26","2":"5"}},{"t":"case","label":"Prestonettes, Inc. v. Coty","cite":"264 U.S. 359","y":1924,"id":"scdb/1923-098","sc":1,"by":{"0":"3, 37"},"q":[{"src":"brief","b":0,"text":"to prohibit the use of it so far as to protect the owner’s good will against the sale of another’s product as his.","cite":"264 U.S. 359, 368"},{"src":"brief","b":0,"text":"only gives the right to prohibit the use of [them] so far as to protect the owner’s good will against the sale of another’s product as his.","cite":"264 U.S. 359, 368"}]},{"t":"case","label":"Qualitex Co. v. Jacobson Prods. Co.","cite":"514 U.S. 159","y":1995,"id":"1994/93-1577","sc":1,"by":{"0":"3, 34"},"q":[{"src":"brief","b":0,"text":"helps assure a producer that it (and not an imitating competitor) will reap the financial, reputation-related rewards associated with a desirable product.","cite":"514 U.S. 159, 164"},{"src":"brief","b":0,"text":"‘reduce the customer’s costs of shopping and making purchasing decisions.’","cite":"514 U.S. 159, 163-164"}]},{"t":"case","label":"R. A. V. v. City of St. Paul","cite":"505 U.S. 377","y":1992,"id":"1991/90-7675","sc":1,"by":{"0":"12, 20, 27, 28","1":"16","2":"2, 7"},"q":[{"src":"brief","b":0,"text":"mode of expressing whatever idea the speaker wishes to convey.","cite":"505 U.S. 377, 393"},{"src":"brief","b":1,"text":"mode of expressing whatever idea the speaker wishes to convey.","cite":"505 U.S. 377, 393"},{"src":"brief","b":2,"text":"mode of expressing whatever idea the speaker wishes to convey.","cite":"505 U.S. 377, 393"},{"src":"argument","who":"Mr. Sommer","text":"They were back when Paul Revere put his name on silverware, but if it was nowadays, Paul Revere would say, I ride for freedom, and that would be viewpoint."}]},{"t":"case","label":"Reed v. Town of Gilbert","cite":"135 S. Ct. 2218","y":2015,"id":"2014/13-502","sc":1,"by":{"0":"19","1":"9, 19, 20, 21","2":"3, 4"},"q":[{"src":"brief","b":0,"text":"may be justified only if the government proves that [it is] narrowly tailored to serve compelling state interests.","cite":"135 S. Ct. 2218, 2226"},{"src":"brief","b":1,"text":"a law applies to particular speech because of the topic discussed or the idea or message expressed.","cite":"135 S. Ct. 2218, 2227"},{"src":"brief","b":1,"text":"law cannot be regarded as protecting an interest of the highest order, and thus as justifying a restriction on truthful speech, when it leaves appreciable damage to that supposedly vital interest unprohibited,","cite":"135 S. Ct. at 2232"}]},{"t":"case","label":"Regan v. Taxation With Representation of Wash.","cite":"461 U.S. 540","y":1983,"id":"1982/81-2338","sc":1,"by":{"0":"9, 23, 31, 43","2":"14"},"q":[{"src":"brief","b":0,"text":"[a] legislature’s decision not to subsidize the exercise of a fundamental right does not infringe the right, and thus is not subject to strict scrutiny,","cite":"461 U.S. at 549"}]},{"t":"case","label":"Rosenberger v. Rector & Visitors of Univ. of Va.","cite":"515 U.S. 819","y":1995,"id":"1994/94-329","sc":1,"by":{"0":"17, 18, 30, 31"},"q":[{"src":"brief","b":0,"text":"an egregious form of content discrimination,","cite":"515 U.S. 819, 829"},{"src":"opinion","who":"Justice Sotomayor, concurring in part and dissenting in part","text":"the government targets not subject matter, but particular views taken by speakers on a subject.","cite":"515 U. S. 819, 829"},{"src":"opinion","who":"Justice Sotomayor, concurring in part and dissenting in part","text":"the government target[ing] . . . particular views taken by speakers on a subject.","cite":"515 U. S., at 829"}]},{"t":"case","label":"Rust v. Sullivan","cite":"500 U.S. 173","y":1991,"id":"1990/89-1391","sc":1,"by":{"0":"23, 25, 32, 45","2":"4, 13"},"q":[{"src":"brief","b":0,"text":"encourage certain activities 2 These are the relevant inquiries under the Free Speech Clause. Other constitutional provisions afford additional protection against, for example, refusing registration on the basis of a suspect classification, such as race or national origin, see Regan, 461 U.S. at 546547, or on the basis of the mark owner’s religious identity or beliefs, see Trinity Lutheran Church of Columbia, Inc. v. Comer, 137 S. Ct. 2012, 2019 (2017). it believes to be in the public interest.","cite":"500 U.S. at 193"},{"src":"brief","b":2,"text":"encourage certain activities it believes to be in the public interest.","cite":"500 U.S. at 193"}]},{"t":"case","label":"San Francisco Arts & Athletics, Inc. v. United States Olympic Comm.","cite":"483 U.S. 522","y":1987,"id":"1986/86-270","sc":1,"by":{"0":"36"}},{"t":"case","label":"Trinity Lutheran Church of Columbia, Inc. v. Comer","cite":"137 S. Ct. 2012","y":2017,"id":"2016/15-577","sc":1,"by":{"0":"31"}},{"t":"case","label":"Two Pesos, Inc. v. Taco Cabana, Inc.","cite":"505 U.S. 763","y":1992,"id":"1991/91-971","sc":1,"by":{"0":"39"}},{"t":"case","label":"United States v. American Library Ass’n","cite":"539 U.S. 194","y":2003,"id":"2002/02-361","sc":1,"by":{"0":"33","2":"6"},"q":[{"src":"brief","b":2,"text":"in selecting the material it provides to its patrons,","cite":"539 U.S. 194, 204-205"}]},{"t":"case","label":"United States v. Playboy Entm’t Grp., Inc.","cite":"529 U.S. 803","y":2000,"id":"1999/98-1682","sc":1,"by":{"0":"40, 41"}},{"t":"case","label":"United States v. Stevens","cite":"559 U.S. 460","y":2010,"id":"2009/08-769","sc":1,"by":{"0":"47"},"q":[{"src":"opinion","who":"Opinion of the Court (Justice Kagan)","text":"We will not rewrite a law to conform it to constitutional requirements.","cite":"559 U. S. 460, 481"},{"src":"opinion","who":"Justice Sotomayor, concurring in part and dissenting in part","text":"‘a substantial number of [the scandalous-marks provision’s] applications are unconstitutional, judged in relation to the [provision’s] plainly legitimate sweep.’","cite":"559 U. S. 460, 473"}]},{"t":"case","label":"Wal-Mart Stores, Inc. v. Samara Bros.","cite":"529 U.S. 205","y":2000,"id":"1999/99-150","sc":1,"by":{"0":"2, 34, 36, 44"},"q":[{"src":"brief","b":0,"text":"attract an otherwise indifferent consumer’s attention on a crowded store shelf,","cite":"529 U.S. at 212"},{"src":"argument","who":"Mr. Sommer","text":"Well, just granting federal registration doesn't require that anyone use a trademark. And my client's goods are not going to be a target at Wal-Mart."},{"src":"argument","who":"Chief Justice Roberts","text":"-- you say that, you know, this product's not going to be in Wal-Mart, right?"}]},{"t":"case","label":"Ysursa v. Pocatello Educ. Ass’n","cite":"555 U.S. 353","y":2009,"id":"2008/07-869","sc":1,"by":{"0":"passim","1":"30","2":"3, 5, 12, 13"},"q":[{"src":"brief","b":0,"text":"does not confer an affirmative right","cite":"555 U.S. 353, 355"},{"src":"brief","b":0,"text":"a distinction based on the content of speech: Specific consent was required from nonunion members before agency fees could be used for election-related activities, but consent was not required with respect to agency fees used for other purposes.","cite":"555 U.S. at 360"}]},{"t":"const","label":"Amendment I","clauses":[["establishment","Establishment Clause"],["free-exercise","Free Exercise Clause"],["free-speech","Free Speech Clause"],["free-press","Free Press Clause"],["assembly-petition","Assembly, Petition and Association"]],"text":"Congress shall make no law respecting an establishment of religion, or prohibiting the free exercise thereof; or abridging the freedom of speech, or of the press; or the right of the people peaceably to assemble, and to petition the Government for a redress of grievances.","by":{"0":"passim","1":"passim"}},{"t":"usc","label":"15 U.S.C. § 1051","url":"https://www.law.cornell.edu/uscode/text/15/1051","subs":["(a)(1)","(a)(2)","(a)","(b)"],"stext":{"head":"§1051. Application for registration; verification","paras":[[0,"(a) Application for use of trademark"],[0,"(1) The owner of a trademark used in commerce may request registration of its trademark on the principal register hereby established by paying the prescribed fee and filing in the Patent and Trademark Office an application and a verified statement, in such form as may be prescribed by the Director, and such number of specimens or facsimiles of the mark as used as may be required by the Director."],[0,"(2) The application shall include specification of the applicant's domicile and citizenship, the date of the applicant's first use of the mark, the date of the applicant's first use of the mark in commerce, the goods in connection with which the mark is used, and a drawing of the mark."],[0,"(3) The statement shall be verified by the applicant and specify that—"],[1,"(A) the person making the verification believes that he or she, or the juristic person in whose behalf he or she makes the verification, to be the owner of the mark sought to be registered;"],[1,"(B) to the best of the verifier's knowledge and belief, the facts recited in the application are accurate;"],[1,"(C) the mark is in use in commerce; and"],[1,"(D) to the best of the verifier's knowledge and belief, no other person has the right to use such mark in commerce either in the identical form thereof or in such near resemblance thereto as to be likely, when used on or in connection with the goods of such other person, to cause confusion, or to cause mistake, or to deceive, except that, in the case of every application claiming concurrent use, the applicant shall—"],[2,"(i) state exceptions to the claim of exclusive use; and"],[2,"(ii) shall 1 specify, to the extent of the verifier's knowledge—"],[3,"(I) any concurrent use by others;"],[3,"(II) the goods on or in connection with which and the areas in which each concurrent use exists;"],[3,"(III) the periods of each use; and"],[3,"(IV) the goods and area for which the applicant desires registration."],[0,"(4) The applicant shall comply with such rules or regulations as may be prescribed by the Director. The Director shall promulgate rules prescribing the requirements for the application and for obtaining a filing date herein."],[0,"(b) Application for bona fide intention to use trademark"],[0,"(1) A person who has a bona fide intention, under circumstances showing the good faith of such person, to use a trademark in commerce may request registration of its trademark on the principal register hereby established by paying the prescribed fee and filing in the Patent and Trademark Office an application and a verified statement, in such form as may be prescribed by the Director."],[0,"(2) The application shall include specification of the applicant's domicile and citizenship, the goods in connection with which the applicant has a bona fide intention to use the mark, and a drawing of the mark."],[0,"(3) The statement shall be verified by the applicant and specify—"],[1,"(A) that the person making the verification believes that he or she, or the juristic person in whose behalf he or she makes the verification, to be entitled to use the mark in commerce;"],[1,"(B) the applicant's bona fide intention to use the mark in commerce;"],[1,"(C) that, to the best of the verifier's knowledge and belief, the facts recited in the application are accurate; and"],[1,"(D) that, to the best of the verifier's knowledge and belief, no other person has the right to use such mark in commerce either in the identical form thereof or in such near resemblance thereto as to be likely, when used on or in connection with the goods of such other person, to cause confusion, or to cause mistake, or to deceive."],[0,"Except for applications filed pursuant to section 1126 of this title, no mark shall be registered until the applicant has met the requirements of subsections (c) and (d) of this section."],[0,"(4) The applicant shall comply with such rules or regulations as may be prescribed by the Director. The Director shall promulgate rules prescribing the requirements for the application and for obtaining a filing date herein."],[0,"(c) Amendment of application under subsection (b) to conform to requirements of subsection (a)"],[0,"At any time during examination of an application filed under subsection (b), an applicant who has made use of the mark in commerce may claim the benefits of such use for purposes of this chapter, by amending his or her application to bring it into conformity with the requirements of subsection (a)."],[0,"(d) Verified statement that trademark is used in commerce"],[0,"(1) Within six months after the date on which the notice of allowance with respect to a mark is issued under section 1063(b)(2) of this title to an applicant under subsection (b) of this section, the applicant shall file in the Patent and Trademark Office, together with such number of specimens or facsimiles of the mark as used in commerce as may be required by the Director and payment of the prescribed fee, a verified statement that the mark is in use in commerce and specifying the date of the applicant's first use of the mark in commerce and those goods or services specified in the notice of allowance on or in connection with which the mark is used in commerce. Subject to examination and acceptance of the statement of use, the mark shall be registered in the Patent and Trademark Office, a certificate of registration shall be issued for those goods or services recited in the statement of use for which the mark is entitled to registration, and notice of registration shall be published in the Official Gazette of the Patent and Trademark Office. Such examination may include an examination of the factors set forth in subsections (a) through (e) of section 1052 of this title. The notice of registration shall specify the goods or services for which the mark is registered."],[0,"(2) The Director shall extend, for one additional 6-month period, the time for filing the statement of use under paragraph (1), upon written request of the applicant before the expiration of the 6-month period provided in paragraph (1). In addition to an extension under the preceding sentence, the Director may, upon a showing of good cause by the applicant, further extend the time for filing the statement of use under paragraph (1) for periods aggregating not more than 24 months, pursuant to written request of the applicant made before the expiration of the last extension granted under this paragraph. Any request for an extension under this paragraph shall be accompanied by a verified statement that the applicant has a continued bona fide intention to use the mark in commerce and specifying those goods or services identified in the notice of allowance on or in connection with which the applicant has a continued bona fide intention to use the mark in commerce. Any request for an extension under this paragraph shall be accompanied by payment of the prescribed fee. The Director shall issue regulations setting forth guidelines for determining what constitutes good cause for purposes of this paragraph."],[0,"(3) The Director shall notify any applicant who files a statement of use of the acceptance or refusal thereof and, if the statement of use is refused, the reasons for the refusal. An applicant may amend the statement of use."],[0,"(4) The failure to timely file a verified statement of use under paragraph (1) or an extension request under paragraph (2) shall result in abandonment of the application, unless it can be shown to the satisfaction of the Director that the delay in responding was unintentional, in which case the time for filing may be extended, but for a period not to exceed the period specified in paragraphs (1) and (2) for filing a statement of use."],[0,"(e) Designation of resident for service of process and notices"],[0,"If the applicant is not domiciled in the United States the applicant may designate, by a document filed in the United States Patent and Trademark Office, the name and address of a person resident in the United States on whom may be served notices or process in proceedings affecting the mark. Such notices or process may be served upon the person so designated by leaving with that person or mailing to that person a copy thereof at the address specified in the last designation so filed. If the person so designated cannot be found at the address given in the last designation, or if the registrant does not designate by a document filed in the United States Patent and Trademark Office the name and address of a person resident in the United States on whom may be served notices or process in proceedings affecting the mark, such notices or process may be served on the Director."],[0,"(f) Third-party submission of evidence"],[0,"A third party may submit for consideration for inclusion in the record of an application evidence relevant to a ground for refusal of registration. The third-party submission shall identify the ground for refusal and include a concise description of each piece of evidence submitted in support of each identified ground for refusal. Not later than 2 months after the date on which the submission is filed, the Director shall determine whether the evidence should be included in the record of the application. The Director shall establish by regulation appropriate procedures for the consideration of evidence submitted by a third party under this subsection and may prescribe a fee to accompany the submission. If the Director determines that the third-party evidence should be included in the record of the application, only the evidence and the ground for refusal to which the evidence relates may be so included. Any determination by the Director whether or not to include evidence in the record of an application shall be final and non-reviewable, and a determination to include or to not include evidence in the record shall not prejudice any party's right to raise any issue and rely on any evidence in any other proceeding."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1051?type=usc&year=mostrecent&link-type=html"},"by":{"0":"4, 46, 46","2":"16, 16, 16"},"q":[{"src":"brief","b":0,"text":"the goods in connection with which the mark is used.","cite":"15 U.S.C. 1051(a)(2)"}]},{"t":"usc","label":"15 U.S.C. § 1052","url":"https://www.law.cornell.edu/uscode/text/15/1052","subs":["(a)","(b)","(c)","(d)","(e)(1)","(e)(5)"],"stext":{"head":"§1052. Trademarks registrable on principal register; concurrent registration","paras":[[0,"No trademark by which the goods of the applicant may be distinguished from the goods of others shall be refused registration on the principal register on account of its nature unless it—"],[0,"(a) Consists of or comprises immoral, deceptive, or scandalous matter; or matter which may disparage or falsely suggest a connection with persons, living or dead, institutions, beliefs, or national symbols, or bring them into contempt, or disrepute; or a geographical indication which, when used on or in connection with wines or spirits, identifies a place other than the origin of the goods and is first used on or in connection with wines or spirits by the applicant on or after one year after the date on which the WTO Agreement (as defined in section 3501(9) of title 19) enters into force with respect to the United States."],[0,"(b) Consists of or comprises the flag or coat of arms or other insignia of the United States, or of any State or municipality, or of any foreign nation, or any simulation thereof."],[0,"(c) Consists of or comprises a name, portrait, or signature identifying a particular living individual except by his written consent, or the name, signature, or portrait of a deceased President of the United States during the life of his widow, if any, except by the written consent of the widow."],[0,"(d) Consists of or comprises a mark which so resembles a mark registered in the Patent and Trademark Office, or a mark or trade name previously used in the United States by another and not abandoned, as to be likely, when used on or in connection with the goods of the applicant, to cause confusion, or to cause mistake, or to deceive: Provided, That if the Director determines that confusion, mistake, or deception is not likely to result from the continued use by more than one person of the same or similar marks under conditions and limitations as to the mode or place of use of the marks or the goods on or in connection with which such marks are used, concurrent registrations may be issued to such persons when they have become entitled to use such marks as a result of their concurrent lawful use in commerce prior to (1) the earliest of the filing dates of the applications pending or of any registration issued under this chapter; (2) July 5, 1947, in the case of registrations previously issued under the Act of March 3, 1881, or February 20, 1905, and continuing in full force and effect on that date; or (3) July 5, 1947, in the case of applications filed under the Act of February 20, 1905, and registered after July 5, 1947. Use prior to the filing date of any pending application or a registration shall not be required when the owner of such application or registration consents to the grant of a concurrent registration to the applicant. Concurrent registrations may also be issued by the Director when a court of competent jurisdiction has finally determined that more than one person is entitled to use the same or similar marks in commerce. In issuing concurrent registrations, the Director shall prescribe conditions and limitations as to the mode or place of use of the mark or the goods on or in connection with which such mark is registered to the respective persons."],[0,"(e) Consists of a mark which (1) when used on or in connection with the goods of the applicant is merely descriptive or deceptively misdescriptive of them, (2) when used on or in connection with the goods of the applicant is primarily geographically descriptive of them, except as indications of regional origin may be registrable under section 1054 of this title, (3) when used on or in connection with the goods of the applicant is primarily geographically deceptively misdescriptive of them, (4) is primarily merely a surname, or (5) comprises any matter that, as a whole, is functional."],[0,"(f) Except as expressly excluded in subsections (a), (b), (c), (d), (e)(3), and (e)(5) of this section, nothing in this chapter shall prevent the registration of a mark used by the applicant which has become distinctive of the applicant's goods in commerce. The Director may accept as prima facie evidence that the mark has become distinctive, as used on or in connection with the applicant's goods in commerce, proof of substantially exclusive and continuous use thereof as a mark by the applicant in commerce for the five years before the date on which the claim of distinctiveness is made. Nothing in this section shall prevent the registration of a mark which, when used on or in connection with the goods of the applicant, is primarily geographically deceptively misdescriptive of them, and which became distinctive of the applicant's goods in commerce before December 8, 1993."],[0,"A mark which would be likely to cause dilution by blurring or dilution by tarnishment under section 1125(c) of this title, may be refused registration only pursuant to a proceeding brought under section 1063 of this title. A registration for a mark which would be likely to cause dilution by blurring or dilution by tarnishment under section 1125(c) of this title, may be canceled pursuant to a proceeding brought under either section 1064 of this title or section 1092 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1052?type=usc&year=mostrecent&link-type=html"},"by":{"0":"46, 46, 46, 46, 46, 46, 46","1":"passim","2":"6, 10, passim, 23, 23"},"q":[{"src":"brief","b":0,"text":"matter which may disparage * * * persons, living or dead, institutions, beliefs, or national symbols, or bring them into contempt, or disrepute.","cite":"15 U.S.C. 1052(a)"},{"src":"brief","b":0,"text":"immoral * * * or scandalous matter.","cite":"15 U.S.C. 1052(a)"}]},{"t":"usc","label":"15 U.S.C. § 1057","url":"https://www.law.cornell.edu/uscode/text/15/1057","subs":["(a)","(b)"],"stext":{"head":"§1057. Certificates of registration","paras":[[0,"(a) Issuance and form"],[0,"Certificates of registration of marks registered upon the principal register shall be issued in the name of the United States of America, under the seal of the United States Patent and Trademark Office, and shall be signed by the Director or have his signature placed thereon, and a record thereof shall be kept in the United States Patent and Trademark Office. The registration shall reproduce the mark, and state that the mark is registered on the principal register under this chapter, the date of the first use of the mark, the date of the first use of the mark in commerce, the particular goods or services for which it is registered, the number and date of the registration, the term thereof, the date on which the application for registration was received in the United States Patent and Trademark Office, and any conditions and limitations that may be imposed in the registration."],[0,"(b) Certificate as prima facie evidence"],[0,"A certificate of registration of a mark upon the principal register provided by this chapter shall be prima facie evidence of the validity of the registered mark and of the registration of the mark, of the owner's ownership of the mark, and of the owner's exclusive right to use the registered mark in commerce on or in connection with the goods or services specified in the certificate, subject to any conditions or limitations stated in the certificate."],[0,"(c) Application to register mark considered constructive use"],[0,"Contingent on the registration of a mark on the principal register provided by this chapter, the filing of the application to register such mark shall constitute constructive use of the mark, conferring a right of priority, nationwide in effect, on or in connection with the goods or services specified in the registration against any other person except for a person whose mark has not been abandoned and who, prior to such filing—"],[1,"(1) has used the mark;"],[1,"(2) has filed an application to register the mark which is pending or has resulted in registration of the mark; or"],[1,"(3) has filed a foreign application to register the mark on the basis of which he or she has acquired a right of priority, and timely files an application under section 1126(d) of this title to register the mark which is pending or has resulted in registration of the mark."],[0,"(d) Issuance to assignee"],[0,"A certificate of registration of a mark may be issued to the assignee of the applicant, but the assignment must first be recorded in the United States Patent and Trademark Office. In case of change of ownership the Director shall, at the request of the owner and upon a proper showing and the payment of the prescribed fee, issue to such assignee a new certificate of registration of the said mark in the name of such assignee, and for the unexpired part of the original period."],[0,"(e) Surrender, cancellation, or amendment by owner"],[0,"Upon application of the owner the Director may permit any registration to be surrendered for cancellation, and upon cancellation appropriate entry shall be made in the records of the United States Patent and Trademark Office. Upon application of the owner and payment of the prescribed fee, the Director for good cause may permit any registration to be amended or to be disclaimed in part: Provided, That the amendment or disclaimer does not alter materially the character of the mark. Appropriate entry shall be made in the records of the United States Patent and Trademark Office and upon the certificate of registration."],[0,"(f) Copies of United States Patent and Trademark Office records as evidence"],[0,"Copies of any records, books, papers, or drawings belonging to the United States Patent and Trademark Office relating to marks, and copies of registrations, when authenticated by the seal of the United States Patent and Trademark Office and certified by the Director, or in his name by an employee of the Office duly designated by the Director, shall be evidence in all cases wherein the originals would be evidence; and any person making application therefor and paying the prescribed fee shall have such copies."],[0,"(g) Correction of United States Patent and Trademark Office mistake"],[0,"Whenever a material mistake in a registration, incurred through the fault of the United States Patent and Trademark Office, is clearly disclosed by the records of the Office a certificate stating the fact and nature of such mistake shall be issued without charge and recorded and a printed copy thereof shall be attached to each printed copy of the registration and such corrected registration shall thereafter have the same effect as if the same had been originally issued in such corrected form, or in the discretion of the Director a new certificate of registration may be issued without charge. All certificates of correction heretofore issued in accordance with the rules of the United States Patent and Trademark Office and the registrations to which they are attached shall have the same force and effect as if such certificates and their issue had been specifically authorized by statute."],[0,"(h) Correction of applicant's mistake"],[0,"Whenever a mistake has been made in a registration and a showing has been made that such mistake occurred in good faith through the fault of the applicant, the Director is authorized to issue a certificate of correction or, in his discretion, a new certificate upon the payment of the prescribed fee: Provided, That the correction does not involve such changes in the registration as to require republication of the mark."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1057?type=usc&year=mostrecent&link-type=html"},"by":{"0":"46, 46"},"q":[{"src":"brief","b":0,"text":"in the name of the United States of America,","cite":"15 U.S.C. 1057(a)"},{"src":"brief","b":0,"text":"in the name of the United States,","cite":"15 U.S.C. 1057(a)"}]},{"t":"usc","label":"15 U.S.C. § 1062","url":"https://www.law.cornell.edu/uscode/text/15/1062","stext":{"head":"§1062. Publication","paras":[[0,"(a) Examination and publication"],[0,"Upon the filing of an application for registration and payment of the prescribed fee, the Director shall refer the application to the examiner in charge of the registration of marks, who shall cause an examination to be made and, if on such examination it shall appear that the applicant is entitled to registration, or would be entitled to registration upon the acceptance of the statement of use required by section 1051(d) of this title, the Director shall cause the mark to be published in the Official Gazette of the Patent and Trademark Office: Provided, That in the case of an applicant claiming concurrent use, or in the case of an application to be placed in an interference as provided for in section 1066 of this title the mark, if otherwise registrable, may be published subject to the determination of the rights of the parties to such proceedings."],[0,"(b) Refusal of registration; amendment of application; abandonment; extensions of time to respond"],[0,"(1) If the applicant is found not entitled to registration, the examiner shall notify the applicant thereof and of the reasons therefor. The applicant may reply or amend the application, which shall then be reexamined. This procedure may be repeated until the examiner finally refuses registration of the mark or the application is abandoned as described in paragraph (2)."],[0,"(2) After notification under paragraph (1), the applicant shall have a period of 6 months in which to reply or amend the application, or such shorter time that is not less than 60 days, as prescribed by the Director by regulation. If the applicant fails to reply or amend or appeal within the relevant time period, including any extension under paragraph (3), the application shall be deemed to have been abandoned, unless it can be shown to the satisfaction of the Director that the delay in responding was unintentional, in which case the application may be revived and such time may be extended. The Director may prescribe a fee to accompany any request to revive."],[0,"(3) The Director shall provide, by regulation, for extensions of time to respond to the examiner for any time period under paragraph (2) that is less than 6 months. The Director shall allow the applicant to obtain extensions of time to reply or amend aggregating 6 months from the date of notification under paragraph (1) when the applicant so requests. However, the Director may set by regulation the time for individual periods of extension, and prescribe a fee, by regulation, for any extension request. Any request for extension shall be filed on or before the date on which a reply or amendment is due under paragraph (1)."],[0,"(c) Republication of marks registered under prior acts"],[0,"A registrant of a mark registered under the provisions of the Act of March 3, 1881, or the Act of February 20, 1905, may, at any time prior to the expiration of the registration thereof, upon the payment of the prescribed fee file with the Director an affidavit setting forth those goods stated in the registration on which said mark is in use in commerce and that the registrant claims the benefits of this chapter for said mark. The Director shall publish notice thereof with a reproduction of said mark in the Official Gazette, and notify the registrant of such publication and of the requirement for the affidavit of use or nonuse as provided for in subsection (b) of section 1058 of this title. Marks published under this subsection shall not be subject to the provisions of section 1063 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1062?type=usc&year=mostrecent&link-type=html"},"by":{"0":"46","2":"20"}},{"t":"usc","label":"15 U.S.C. § 1063","url":"https://www.law.cornell.edu/uscode/text/15/1063","by":{"0":"46"}},{"t":"usc","label":"15 U.S.C. § 1064","url":"https://www.law.cornell.edu/uscode/text/15/1064","by":{"0":"46"}},{"t":"usc","label":"15 U.S.C. § 1065","url":"https://www.law.cornell.edu/uscode/text/15/1065","stext":{"head":"§1065. Incontestability of right to use mark under certain conditions","paras":[[0,"Except on a ground for which application to cancel may be filed at any time under paragraphs (3), (5), and (6) of section 1064 of this title, and except to the extent, if any, to which the use of a mark registered on the principal register infringes a valid right acquired under the law of any State or Territory by use of a mark or trade name continuing from a date prior to the date of registration under this chapter of such registered mark, the right of the owner to use such registered mark in commerce for the goods or services on or in connection with which such registered mark has been in continuous use for five consecutive years subsequent to the date of such registration and is still in use in commerce, shall be incontestable: Provided, That—"],[1,"(1) there has been no final decision adverse to the owner's claim of ownership of such mark for such goods or services, or to the owner's right to register the same or to keep the same on the register; and"],[1,"(2) there is no proceeding involving said rights pending in the United States Patent and Trademark Office or in a court and not finally disposed of; and"],[1,"(3) an affidavit is filed with the Director within one year after the expiration of any such five-year period setting forth those goods or services stated in the registration on or in connection with which such mark has been in continuous use for such five consecutive years and is still in use in commerce, and other matters specified in paragraphs (1) and (2) hereof; and"],[1,"(4) no incontestable right shall be acquired in a mark which is the generic name for the goods or services or a portion thereof, for which it is registered."],[0,"Subject to the conditions above specified in this section, the incontestable right with reference to a mark registered under this chapter shall apply to a mark registered under the Act of March 3, 1881, or the Act of February 20, 1905, upon the filing of the required affidavit with the Director within one year after the expiration of any period of five consecutive years after the date of publication of a mark under the provisions of subsection (c) of section 1062 of this title."],[0,"The Director shall notify any registrant who files the above-prescribed affidavit of the filing thereof."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1065?type=usc&year=mostrecent&link-type=html"},"by":{"0":"46","1":"49"}},{"t":"usc","label":"15 U.S.C. § 1067","url":"https://www.law.cornell.edu/uscode/text/15/1067","by":{"0":"46"}},{"t":"usc","label":"15 U.S.C. § 1070","url":"https://www.law.cornell.edu/uscode/text/15/1070","by":{"0":"46"}},{"t":"usc","label":"15 U.S.C. § 1071","url":"https://www.law.cornell.edu/uscode/text/15/1071","by":{"0":"46"}},{"t":"usc","label":"15 U.S.C. § 1072","url":"https://www.law.cornell.edu/uscode/text/15/1072","by":{"0":"4, 21"},"q":[{"src":"brief","b":0,"text":"constructive notice of the registrant’s claim of ownership","cite":"15 U.S.C. 1072"}]},{"t":"usc","label":"15 U.S.C. § 1091","url":"https://www.law.cornell.edu/uscode/text/15/1091","by":{"0":"35"}},{"t":"usc","label":"15 U.S.C. § 1111","url":"https://www.law.cornell.edu/uscode/text/15/1111","stext":{"head":"§1111. Notice of registration; display with mark; recovery of profits and damages in infringement suit","paras":[[0,"Notwithstanding the provisions of section 1072 of this title, a registrant of a mark registered in the Patent and Trademark Office, may give notice that his mark is registered by displaying with the mark the words \"Registered in U.S. Patent and Trademark Office\" or \"Reg. U.S. Pat. & Tm. Off.\" or the letter R enclosed within a circle, thus ®; and in any suit for infringement under this chapter by such a registrant failing to give such notice of registration, no profits and no damages shall be recovered under the provisions of this chapter unless the defendant had actual notice of the registration."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1111?type=usc&year=mostrecent&link-type=html"},"by":{"0":"21","2":"15"},"q":[{"src":"brief","b":0,"text":"may give notice that his mark is registered by displaying with the mark the words ‘Registered in U.S. Patent and Trademark Office’ or ‘Reg. U.S. Pat. & Tm. Off.’ or the letter R enclosed within a circle, thus ®,","cite":"15 U.S.C. 1111"},{"src":"brief","b":0,"text":"by displaying with the mark the words ‘Registered in U.S. Patent and Trademark Office’ or ‘Reg. U.S. Pat. & Tm. Off.’ or the letter R enclosed within a circle, thus ®.","cite":"15 U.S.C. 1111"},{"src":"brief","b":2,"text":"the words ‘Registered in U.S. Patent and Trademark Office or ‘Reg. U.S. Pat. & Tm. Off.’","cite":"15 U.S.C. 1111"}]},{"t":"usc","label":"15 U.S.C. § 1114","url":"https://www.law.cornell.edu/uscode/text/15/1114","subs":["(1)(a)"],"by":{"0":"21"}},{"t":"usc","label":"15 U.S.C. § 1115","url":"https://www.law.cornell.edu/uscode/text/15/1115","subs":["(a)","(b)"],"by":{"0":"21, 21"},"q":[{"src":"brief","b":0,"text":"prima facie evidence of the validity of the registered mark * * * and of the registrant’s exclusive right to use the registered mark in commerce on or in connection with the goods or services specified in the registration.","cite":"15 U.S.C. 1115(a)"}]},{"t":"usc","label":"15 U.S.C. § 1116","url":"https://www.law.cornell.edu/uscode/text/15/1116","by":{"0":"21"}},{"t":"usc","label":"15 U.S.C. § 1117","url":"https://www.law.cornell.edu/uscode/text/15/1117","subs":["(a)"],"by":{"0":"21"}},{"t":"usc","label":"15 U.S.C. § 1124","url":"https://www.law.cornell.edu/uscode/text/15/1124","by":{"0":"21"}},{"t":"usc","label":"15 U.S.C. § 1125","url":"https://www.law.cornell.edu/uscode/text/15/1125","subs":["(a)","(a)(1)","(b)","(c)","(d)"],"by":{"0":"21, 21, 39, 39, 39, 39, 35"}},{"t":"usc","label":"15 U.S.C. § 1141b","url":"https://www.law.cornell.edu/uscode/text/15/1141b","by":{"0":"35"}},{"t":"usc","label":"17 U.S.C. § 102","url":"https://www.law.cornell.edu/uscode/text/17/102","subs":["(a)"],"by":{"0":"44"},"q":[{"src":"brief","b":0,"text":"original works of authorship fixed in a[] tangible medium of expression.","cite":"17 U.S.C. 102(a)"}]},{"t":"usc","label":"35 U.S.C. § 2","url":"https://www.law.cornell.edu/uscode/text/35/2","subs":["(a)(1)"],"by":{"0":"5"}},{"t":"case","label":"Ass’n of Bituminous Contractors, Inc. v. Apfel","cite":"156 F.3d 1246","y":1998,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/156/1246/","by":{"1":"56"}},{"t":"case","label":"Bad Frog Brewery v. New York State Liquor Authority","cite":"134 F.3d 87","y":1998,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/134/87/","by":{"1":"49"}},{"t":"case","label":"Barnhart v. Sigmon Coal Co.","cite":"534 U.S. 438","y":2002,"id":"2001/00-1307","sc":1,"by":{"1":"37"}},{"t":"case","label":"Bolger v. Youngs Drug Prods. Corp.","cite":"463 U.S. 60","y":1983,"id":"1982/81-1590","sc":1,"by":{"1":"22"}},{"t":"case","label":"Bouie v. City of Columbia","cite":"378 U.S. 347","y":1964,"id":"1963/10","sc":1,"by":{"1":"59"}},{"t":"case","label":"Brown v. Entertainment Merchants Ass’n","cite":"564 U.S. 786","y":2011,"id":"2010/08-1448","sc":1,"by":{"1":"34"},"q":[{"src":"brief","b":1,"text":"Vague laws force potential speakers to steer far wider of the unlawful zone . . . than if the boundaries of the forbidden areas were clearly marked.","cite":"564 U.S. 786, 807"}]},{"t":"case","label":"City of Dubuque v. Ill. Central R. Co.","cite":"39 Iowa 56","y":1874,"url":"https://www.courtlistener.com/c/Iowa/39/56/","by":{"1":"51"},"q":[{"src":"brief","b":1,"text":"There must be a concurrence of a majority of the judges upon the principles, rules of law, announced in the case, before they can be considered settled by a decision. If the court be equally divided or less than a majority concur in a rule, no one will claim that it has the force of the authority of the court.","cite":"39 Iowa 56, 80"}]},{"t":"case","label":"City of Lakewood v. Plain Dealer Pub. Co.","cite":"486 U.S. 750","y":1988,"id":"1987/86-1042","sc":1,"by":{"1":"61, 62"},"q":[{"src":"brief","b":1,"text":"As the plurality opinion in MITE did not represent the views of a majority of the Court, we are not bound by its reasoning.","cite":"486 U.S. 750, 764 n.9"}]},{"t":"case","label":"Consolidated Edison Co. v. Public Svc. Comm’n","cite":"447 U.S. 530","y":1980,"id":"1979/79-134","sc":1,"by":{"1":"19"},"q":[{"src":"brief","b":1,"text":"applicable to all speech irrespective of content.","cite":"447 U.S. 530, 536"}]},{"t":"case","label":"CTS Corp. v. Dynamics Corp. of Am.","cite":"481 U.S. 69","y":1987,"id":"1986/86-71","sc":1,"by":{"1":"61"}},{"t":"case","label":"FCC v. Fox Television Stations, Inc.","cite":"132 S. Ct. 2307","y":2012,"id":"2011/10-1293","sc":1,"by":{"1":"33, 34"},"q":[{"src":"brief","b":1,"text":"requires the invalidation of laws that are impermissibly vague.","cite":"132 S. Ct. 2307, 2317"}]},{"t":"case","label":"Freeman v. United States","cite":"564 U.S. 522","y":2011,"id":"2010/09-10245","sc":1,"by":{"1":"52, 57"}},{"t":"case","label":"Grayned v. City of Rockford","cite":"408 U.S. 104","y":1972,"id":"1971/70-5106","sc":1,"by":{"1":"34"},"q":[{"src":"brief","b":1,"text":"for resolution on an ad hoc and subjective basis, with the attendant dangers of arbitrary and discriminatory application.","cite":"408 U.S. 104, 108-09"}]},{"t":"case","label":"Gregg v. Georgia","cite":"428 U.S. 153","y":1976,"id":"1975/74-6257","sc":1,"by":{"1":"58, 59"}},{"t":"case","label":"Grutter v. Bollinger","cite":"539 U.S. 306","y":2003,"id":"2002/02-241","sc":1,"by":{"1":"62","2":"19"},"q":[{"src":"brief","b":1,"text":"[t]his test is more easily stated than applied to the various opinions supporting the result in [the referenced plurality decision].","cite":"539 U.S. 306, 325"}]},{"t":"case","label":"Hess v. Indiana","cite":"414 U.S. 105","y":1973,"id":"1973/73-5290","sc":1,"by":{"1":"19"}},{"t":"case","label":"Hughes v. United States","cite":"138 S. Ct 1765","y":2018,"url":"https://www.courtlistener.com/c/S.%20Ct/138/1765/","by":{"1":"50, 53, 58, 63"}},{"t":"case","label":"Hustler Magazine, Inc. v. Falwell","cite":"485 U.S. 46","y":1988,"id":"1987/86-1278","sc":1,"by":{"1":"22"},"q":[{"src":"brief","b":1,"text":"[T]he fact that society may find speech offensive is not a sufficient reason for suppressing it.","cite":"485 U.S. 46, 55"}]},{"t":"case","label":"Kalman v. Cortes","cite":"723 F. Supp. 2d 766","y":2010,"court":"E.D. Pa.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/723/766/","by":{"1":"49"}},{"t":"case","label":"King v. Palmer","cite":"950 F.2d 771","y":1991,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/950/771/","by":{"1":"56"}},{"t":"case","label":"Lewis v. City of New Orleans","cite":"415 U.S. 130","y":1974,"id":"1973/72-6156","sc":1,"by":{"1":"19"}},{"t":"case","label":"Marks v. United States","cite":"430 U.S. 188","y":1977,"id":"1976/75-708","sc":1,"by":{"1":"passim","2":"18"},"q":[{"src":"brief","b":1,"text":"The view of the Memoirs plurality therefore constituted the holding of the Court and provided the governing standards.","cite":"430 U.S. at 194"}]},{"t":"case","label":"Memoirs v. Massachusetts","cite":"383 U.S. 413","y":1966,"id":"1965/368","sc":1,"by":{"1":"59, 60"}},{"t":"case","label":"Nichols v. United States","cite":"511 U.S. 738","y":1994,"id":"1993/92-8556","sc":1,"by":{"1":"50, 62","2":"19"},"q":[{"src":"brief","b":2,"text":"pursu[ing] the Marks inquiry to the utmost logical possibility.","cite":"511 U.S. 738, 746"}]},{"t":"case","label":"Papish v. Board of Curators, Univ. of Missouri","cite":"410 U.S. 667","y":1973,"id":"1972/72-794","sc":1,"by":{"1":"19"}},{"t":"case","label":"Paris Adult Theatre I v. Slaton","cite":"413 U.S. 49","y":1973,"id":"1972/71-1051","sc":1,"by":{"1":"58"}},{"t":"case","label":"Pearson v. Callahan","cite":"555 U.S. 223","y":2009,"id":"2008/07-751","sc":1,"by":{"1":"64"}},{"t":"case","label":"Pro-Football, Inc. v. Harjo","cite":"415 F.3d 44","y":2005,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/415/44/","by":{"1":"49"}},{"t":"case","label":"Rapanos v. United States","cite":"547 U.S. 715","y":2006,"id":"2005/04-1034","sc":1,"by":{"1":"55"}},{"t":"case","label":"Regents of Univ. of Cal. v. Bakke","cite":"438 U.S. 265","y":1978,"id":"1979/76-811","sc":1,"by":{"1":"62"},"q":[{"src":"brief","b":1,"text":"It does not seem ‘useful to pursue the Marks inquiry to the utmost logical possibility when it has so obviously baffled and divided the lower courts that have considered it.’","cite":"438 U.S. 265"}]},{"t":"case","label":"Reno v. American Civil Liberties Union","cite":"521 U.S. 844","y":1997,"id":"1996/96-511","sc":1,"by":{"1":"38"},"q":[{"src":"brief","b":1,"text":"raises special First Amendment concerns because of its obvious chilling effect on free speech.","cite":"521 U.S. at 871"},{"src":"argument","who":"Mr. Sommer","text":"And that sort of falls afoul of Reno versus ACLU, that says we can't take our level of discussion in our diverse society that includes, for example, a rapper --"}]},{"t":"case","label":"Roth v. United States","cite":"354 U.S. 476","y":1957,"id":"1956/582","sc":1,"by":{"1":"59, 60, 61"}},{"t":"case","label":"Sambo’s Restaurants, Inc. v. City of Ann Arbor","cite":"663 F.2d 686","y":1981,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/663/686/","by":{"1":"49"}},{"t":"case","label":"Speiser v. Randall","cite":"357 U.S. 513","y":1958,"id":"1957/483","sc":1,"by":{"1":"29"}},{"t":"case","label":"Street v. New York","cite":"394 U.S. 576","y":1969,"id":"1968/5","sc":1,"by":{"1":"10"}},{"t":"case","label":"Texas v. Johnson","cite":"491 U.S. 397","y":1989,"id":"1988/88-155","sc":1,"by":{"1":"10"}},{"t":"case","label":"Turner Broadcasting Sys., Inc. v. FCC","cite":"512 U.S. 622","y":1994,"id":"1993/93-44","sc":1,"by":{"1":"18, 21"},"q":[{"src":"brief","b":1,"text":"governmental control over the content of messages expressed by private individuals.","cite":"512 U.S. 622, 641"}]},{"t":"case","label":"United States v. Duvall","cite":"740 F.3d 604","y":2013,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/740/604/","by":{"1":"56, 65"},"q":[{"src":"brief","b":1,"text":"[T]he necessary logical corollary to Marks is that lower courts should still strive to decide the case before them in a way consistent with how the Supreme Court’s opinions in the relevant precedent would resolve the current case.","cite":"740 F.3d 604, 611"}]},{"t":"case","label":"United States v. Pink","cite":"315 U.S. 203","y":1942,"id":"1940-1955/315us203","sc":1,"by":{"1":"52"}},{"t":"case","label":"United States v. Robertson","cite":"875 F.3d 1281","y":2017,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/875/1281/","by":{"1":"55"}},{"t":"const","label":"Amendment V","clauses":[["grand-jury","Grand Jury Clause"],["double-jeopardy","Double Jeopardy Clause"],["self-incrimination","Self-Incrimination Clause"],["due-process-5","Due Process Clause (Fifth Amendment)"],["takings","Takings Clause"]],"text":"No person shall be held to answer for a capital, or otherwise infamous crime, unless on a presentment or indictment of a Grand Jury, except in cases arising in the land or naval forces, or in the Militia, when in actual service in time of War or public danger; nor shall any person be subject for the same offence to be twice put in jeopardy of life or limb; nor shall be compelled in any criminal case to be a witness against himself, nor be deprived of life, liberty, or property, without due process of law; nor shall private property be taken for public use, without just compensation.","by":{"1":"1","2":"19"}},{"t":"const","label":"Amendment XII","text":"The Electors shall meet in their respective states and vote by ballot for President and Vice-President, one of whom, at least, shall not be an inhabitant of the same state with themselves; they shall name in their ballots the person voted for as President, and in distinct ballots the person voted for as Vice-President, and they shall make distinct lists of all persons voted for as President, and of all persons voted for as Vice-President, and of the number of votes for each, which lists they shall sign and certify, and transmit sealed to the seat of the government of the United States, directed to the President of the Senate; -- the President of the Senate shall, in the presence of the Senate and House of Representatives, open all the certificates and the votes shall then be counted; -- The person having the greatest number of votes for President, shall be the President, if such number be a majority of the whole number of Electors appointed; and if no person have such majority, then from the persons having the highest numbers not exceeding three on the list of those voted for as President, the House of Representatives shall choose immediately, by ballot, the President. But in choosing the President, the votes shall be taken by states, the representation from each state having one vote; a quorum for this purpose shall consist of a member or members from two-thirds of the states, and a majority of all the states shall be necessary to a choice. [And if the House of Representatives shall not choose a President whenever the right of choice shall devolve upon them, before the fourth day of March next following, then the Vice-President shall act as President, as in the case of the death or other constitutional disability of the President. --] The person having the greatest number of votes as Vice-President, shall be the Vice-President, if such number be a majority of the whole number of Electors appointed, and if no person have a majority, then from the two highest numbers on the list, the Senate shall choose the Vice-President; a quorum for the purpose shall consist of two-thirds of the whole number of Senators, and a majority of the whole number shall be necessary to a choice. But no person constitutionally ineligible to the office of President shall be eligible to that of Vice-President of the United States.","by":{"1":"54"}},{"t":"usc","label":"28 U.S.C. § 2284","url":"https://www.law.cornell.edu/uscode/text/28/2284","subs":["(a)"],"by":{"1":"54"}},{"t":"usc","label":"28 U.S.C. § 46","url":"https://www.law.cornell.edu/uscode/text/28/46","subs":["(c)"],"by":{"1":"54"}},{"t":"case","label":"Denver Area Educ. Telecomms. Consortium, Inc. v. FCC","cite":"518 U.S. 727","y":1996,"id":"1995/95-124","sc":1,"by":{"2":"8"}},{"t":"case","label":"Holder v. Humanitarian Law Project","cite":"561 U.S. 1","y":2010,"id":"2009/08-1498","sc":1,"by":{"2":"20"},"q":[{"src":"brief","b":2,"text":"cannot complain of the vagueness of the law as applied to the conduct of others.","cite":"561 U.S. 1, 19"}]},{"t":"case","label":"Hughes v. United States","cite":"138 S. Ct. 1765","y":2018,"id":"2017/17-155","sc":1,"by":{"2":"19"}},{"t":"case","label":"Hydra Mac, Inc. v. Mack Trucks, Inc.","cite":"507 F.2d 1399","y":1975,"court":"C.C.P.A.","url":"https://www.courtlistener.com/c/F.2d/507/1399/","by":{"2":"10"}},{"t":"case","label":"Koontz v. St. Johns River Water Mgmt. Dist.","cite":"570 U.S. 595","y":2013,"id":"2012/11-1447","sc":1,"by":{"2":"17"}},{"t":"case","label":"McCullen v. Coakley","cite":"573 U.S. 464","y":2014,"id":"2013/12-1168","sc":1,"by":{"2":"17"},"q":[{"src":"brief","b":2,"text":"preserve an uninhibited marketplace of ideas in which truth will ultimately prevail,","cite":"573 U.S. 464, 476"}]},{"t":"case","label":"Rubin v. Coors Brewing Co.","cite":"514 U.S. 476","y":1995,"id":"1994/93-1631","sc":1,"by":{"2":"17"}},{"t":"case","label":"Seabrook Foods, Inc. v. Bar-Well Foods Ltd.","cite":"568 F.2d 1342","y":1977,"court":"C.C.P.A.","url":"https://www.courtlistener.com/c/F.2d/568/1342/","by":{"2":"10"}},{"t":"case","label":"Taniguchi v. Kan Pac. Saipan, Ltd.","cite":"566 U.S. 560","y":2012,"id":"2011/10-1472","sc":1,"by":{"2":"22"}},{"t":"case","label":"Yates v. United States","cite":"135 S. Ct. 1074","y":2015,"id":"2014/13-7451","sc":1,"by":{"2":"23"},"q":[{"src":"brief","b":2,"text":"the same words, placed in different contexts, sometimes mean different things,","cite":"135 S. Ct. 1074, 1082"}]},{"t":"usc","label":"15 U.S.C. § 1127","url":"https://www.law.cornell.edu/uscode/text/15/1127","by":{"2":"15"},"q":[{"src":"brief","b":2,"text":"any word, name, symbol, or device, or any combination thereof * * * used by a person * * * to identify and distinguish his or her goods * * * from those manufactured or sold by others and to indicate the source of the goods.","cite":"15 U.S.C. 1127"}]}]};